def is_valid_gray_code_step(a, b):
    if len(a) != len(b) or len(a) == 0:
        return False
    for ch in a + b:
        if ch not in '01':
            return False
    differences = sum(1 for x, y in zip(a, b) if x != y)
    return differences == 1

