def count_char_type_groups(s):
    if not s:
        return 0
    def category(ch):
        if ch.isalpha():
            return 'alpha'
        if ch.isdigit():
            return 'digit'
        return 'other'
    count = 1
    prev = category(s[0])
    for ch in s[1:]:
        cur = category(ch)
        if cur != prev:
            count += 1
            prev = cur
    return count

def longest_increasing_run(lst):
    if len(lst) == 0:
        return 0
    longest = 1
    run = 1
    for idx in range(1, len(lst)):
        if lst[idx] > lst[idx - 1]:
            run += 1
        else:
            run = 1
        if run > longest:
            longest = run
    return longest

def week_end_date(year, month, day):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        lengths = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[m - 1]

    def sakamoto_dow(y, m, d):
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        yy = y - 1 if m < 3 else y
        return (yy + yy // 4 - yy // 100 + yy // 400 + t[m - 1] + d) % 7

    monday_index = (sakamoto_dow(year, month, day) + 6) % 7
    y, m, d = year, month, day
    for _ in range(6 - monday_index):
        d += 1
        if d > days_in_month(y, m):
            d = 1
            m += 1
            if m > 12:
                m = 1
                y += 1
    return (y, m, d)

